export const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
export function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s}
export function score(records,campaign,people){return people.filter(p=>campaign.members.includes(p.id)).map(p=>({...p,total:records.filter(r=>r.seller===p.id&&norm(r.status)===norm(campaign.event)&&r.date>=campaign.start&&r.date<=campaign.end).length*campaign.points})).sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name,'pt-BR'))}
export function review(rows,state){const seen=new Set();return rows.map(row=>{const errors=[];const id=String(row.id??'').trim();const seller=state.people.find(p=>norm(p.id)===norm(row.seller)||norm(p.name)===norm(row.seller));const status=norm(row.status);if(!id)errors.push('ID da venda obrigatório');if(seen.has(id))errors.push('ID repetido nesta planilha');seen.add(id);if(!seller)errors.push('Vendedor não encontrado');if(!validDate(row.date))errors.push('Data inválida (AAAA-MM-DD)');if(!['ativada','pendente','cancelada','aprovada','fechada'].includes(status))errors.push('Status não reconhecido');const old=state.records.find(r=>r.id===id);const record={id,seller:seller?.id??row.seller,date:row.date,product:row.product||'Internet',status,value:row.value||''};return {record,errors,kind:old?'update':'new',unchanged:old&&JSON.stringify(old)===JSON.stringify(record)}})}
export function applyRows(records,reviewed){if(reviewed.some(r=>r.errors.length))throw Error('Corrija as linhas com erro');const map=new Map(records.map(r=>[r.id,r]));reviewed.forEach(r=>map.set(r.record.id,r.record));return [...map.values()]}
export function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0];const sep=first.includes(';')?';':',';const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===sep&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(quoted)throw Error('Aspas não fechadas na planilha');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
export function mapSheet(rows){const keys=rows.shift()?.map(norm)??[];const aliases={id:['id_venda','id da venda','id'],seller:['vendedor','id_vendedor','seller'],date:['data_ativacao','data','data de ativacao'],product:['produto','product'],status:['status'],value:['valor','value']};for(const k of ['id','seller','date','status'])if(!keys.some(x=>aliases[k].includes(x)))throw Error('Coluna obrigatória ausente: '+aliases[k][0]);return rows.filter(r=>r.some(x=>String(x).trim())).map(r=>Object.fromEntries(Object.entries(aliases).map(([k,a])=>{let v=r[keys.findIndex(x=>a.includes(x))]??'';if(k==='date'){if(/^\d{2}\/\d{2}\/\d{4}$/.test(v))v=v.split('/').reverse().join('-');else if(/^\d{5}$/.test(v))v=new Date((Number(v)-25569)*86400000).toISOString().slice(0,10)}return [k,String(v).trim()]})))}
